SELECT country, DATE_TRUNC('MONTH', started_at) AS activity_month, DATE_TRUNC('WEEK', started_at) AS week_start, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, COUNT(CASE WHEN browser = 'Firefox' THEN 1 END) AS firefox_count, COUNT(DISTINCT device) AS distinct_devices, MIN(started_at) AS started_at, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes_2, COUNT(*) AS event_count FROM sessions GROUP BY country, DATE_TRUNC('MONTH', started_at), DATE_TRUNC('WEEK', started_at) HAVING (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 < 0
